def shortest(graph, start, goal):
    best = {start: 0}
    frontier = [start]
    while frontier:
        node = frontier.pop(0)
        for nxt, w in graph.get(node, {}).items():
            if nxt not in best:
                best[nxt] = best[node] + w
                frontier.append(nxt)
    return best.get(goal), []

